function showStudentChoice(title,action,extra={}) { showModal(title,`<p class="muted">Choose the person for this ${action==='confirm-new-letter'?'application':'document group'}.</p><label for="choose-student">Person</label><select id="choose-student"><option value="">Choose a person…</option>${personOptions()}</select>${Object.entries(extra).map(([k,v])=>`<input type="hidden" id="choice-${esc(k)}" value="${esc(v)}">`).join('')}<p id="modal-error" class="error-text"></p>`,`${button('Cancel','close-modal')}${button('Continue',action,'primary')}`); }
async function createLetter(studentId) {
  if(!studentId) throw new Error('Choose a person first.');
  const l=await api('/api/letters',{student_id:studentId,title:'New application',purpose:'',recipient_lines:[],salutation:'Dear Selection Committee:',date:today(),strength:'',body:'',selected_facts:[],notes:''});
  state.letterDrafts.set(l.id,l);state.details.delete(studentId);closeModal();await refreshBootstrap();await openLetter(l.id);toast('New application letter created.');
}
async function reuseLetter() {const d=letterDraft(state.letter);const payload={};['student_id','title','purpose','recipient_lines','salutation','strength','body','selected_facts','notes'].forEach(k=>payload[k]=structuredClone(d[k]??''));payload.title=(d.title||'Letter')+' — new application';payload.date=today();payload.approved_style_example=false;payload.historical=false;payload.needs_review=!!d.needs_review;const l=await api('/api/letters',payload);state.letterDrafts.set(l.id,l);state.details.delete(l.student_id);await refreshBootstrap();await openLetter(l.id);toast('New application copy created. Update its recipient and purpose.');return l;}
async function saveStudent() {
  const d=studentDraft(state.selected),id=state.selected,version=d._version,manualCoursesChanged=JSON.stringify(d.other_courses||[])!==JSON.stringify(state.details.get(id)?.other_courses||[]),gradeLinkChanged=d.grade_course_id!==state.details.get(id)?.grade_course_id,coursesChanged=manualCoursesChanged||gradeLinkChanged,payload={};['name','netid','ruid','pronouns','aliases','notes','person_type','other_courses','grade_course_id'].forEach(k=>{if(d[k]!==undefined)payload[k]=d[k];});
  if($('#course-history-reviewed')?.checked)payload.course_history_reviewed=true;
  const result=await api(`/api/students/${encodeURIComponent(id)}`,payload);state.details.set(result.id,result);if(coursesChanged){for(const [letterId,draft] of state.letterDrafts){if(draft.student_id!==id)continue;if(!draft._dirty)state.letterDrafts.delete(letterId);else{draft.selected_facts=(draft.selected_facts||[]).filter(f=>String(f).startsWith('other-course:')?!manualCoursesChanged:!gradeLinkChanged);draft._version=(draft._version||0)+1;}}}if(state.studentDrafts.get(id)?._version===version)state.studentDrafts.delete(result.id);await refreshBootstrap();if(state.view==='students')renderStudents();status();toast(state.studentDrafts.get(id)?._dirty?'Saved. Your newer edits still need saving.':'Person information saved.');return result;
}
async function saveLetter(quiet=false) {
  const d=letterDraft(state.letter),version=d._version,payload={};['title','purpose','recipient_lines','salutation','date','strength','body','selected_facts','notes'].forEach(k=>payload[k]=d[k]??(k==='recipient_lines'||k==='selected_facts'?[]:''));payload.approved_style_example=!!d.approved_style_example;payload.needs_review=!!d.needs_review;
  const result=await api(`/api/letters/${encodeURIComponent(d.id)}`,payload);if(state.letterDrafts.get(result.id)?._version===version)state.letterDrafts.set(result.id,result);cacheSavedLetter(result);status();if(!quiet)toast(state.letterDrafts.get(result.id)?._dirty?'Saved. Your newer edits still need saving.':'Letter saved.');return result;
}
function modalError(error) { const el=$('#modal-error');if(el)el.textContent=error.message;else toast(error.message,true); }
async function prepareBrief() {
  const l=letterDraft(state.letter);if(l._dirty)await saveLetter(true);
  if(letterDraft(state.letter)._dirty)throw new Error('Please save your latest letter edits before preparing a brief.');
  if(state.studentDrafts.get(l.student_id)?._dirty)throw new Error('Save the person’s interview notes before preparing a brief so it uses your latest changes.');
  showModal('Prepare an anonymized drafting brief',`<p>Your notes, application instructions, and writing preferences will be assembled locally. The app does not contact ChatGPT.</p><label class="check-label"><input type="checkbox" id="brief-grades" checked><span>Include the course facts selected for this letter.</span></label><label class="check-label" style="margin-top:12px"><input type="checkbox" id="brief-ranks"><span>Include available rankings for those semesters, with cohort context.</span></label><div class="notice amber">Names are replaced with placeholders. Unusual experiences, institutions, and details in free-form notes could still identify the person. Review before sharing.</div><p id="modal-error" class="error-text"></p>`,`${button('Cancel','close-modal')}${button('Create local preview','generate-brief','primary')}`);
}
async function generateBrief() {
  const options={include_grades:$('#brief-grades').checked,include_ranks:$('#brief-ranks').checked,reviewed:false};
  const result=await api(`/api/letters/${encodeURIComponent(state.letter)}/brief`,options);
  state.brief={...result,options,letter_id:state.letter};
  showModal('Review before sharing',`<p class="muted tiny">This preview has been prepared entirely on your computer. Nothing has been sent to an AI service.</p>${result.flagged_terms?.length?`<div class="notice amber"><strong>Review notes</strong>${result.flagged_terms.map(term=>`<p>${esc(term)}</p>`).join('')}</div>`:''}<label for="brief-text">Drafting brief</label><textarea id="brief-text" style="min-height:340px;font-family:Consolas,monospace;font-size:12px">${esc(result.text)}</textarea><label class="check-label" style="margin-top:16px"><input id="brief-reviewed" type="checkbox"><span>I have reviewed this brief and removed any identifying details I do not want to share.</span></label><p id="modal-error" class="error-text"></p>`,`${button('Close','close-modal')}${button('Copy reviewed brief','copy-brief','primary')}${button('Download .txt','download-brief')}${button('Draft with General AI','draft-local-ai','primary')}${button('Redacted online handoff','redacted-online-ai')}`);
}
async function reviewedBrief(download) {
  if(!$('#brief-reviewed').checked)throw new Error('Review the brief and check the confirmation before copying or downloading.');
  const text=$('#brief-text').value;
  await api(`/api/letters/${encodeURIComponent(state.brief.letter_id)}/brief`,{...state.brief.options,reviewed:true,text});
  // Export exactly the text the user reviewed, including their local redactions.
  if(download){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`Drafting-Brief-${state.brief.letter_id}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Reviewed brief downloaded.');}
  else {try{await navigator.clipboard.writeText(text);toast('Reviewed brief copied.');}catch{ $('#brief-text').focus();$('#brief-text').select();throw new Error('Clipboard access is unavailable. The reviewed text is selected; press Ctrl+C.');}}
}
async function aiFromReviewedBrief(mode) {
  if(!$('#brief-reviewed').checked)throw new Error('Review the brief and check the confirmation before using it for drafting.');
  const letterId=state.brief.letter_id;
  const result=await api(`/api/letters/${encodeURIComponent(letterId)}/brief`,{...state.brief.options,reviewed:true,text:$('#brief-text').value});
  const brief=result.path.split(/[\\/]/).pop();
  await LocalDrafting.open({mode,brief,target:{letterId},token:state.boot.token,onApplied:async()=>{
    closeModal();const saved=await api(`/api/letters/${encodeURIComponent(letterId)}`);state.letterDrafts.set(letterId,saved);cacheSavedLetter(saved);
    if(state.letter===letterId)renderLetter();status();toast('Draft saved for review. No signed final was created.');
  }});
}
async function buildLetter(final) {
  const l=letterDraft(state.letter);if(final&&l.historical)throw new Error('Copy this original letter for another application before creating a new signed version.');if(l._dirty)await saveLetter(true);
  if(letterDraft(state.letter)._dirty)throw new Error('Please save your latest letter edits before building a PDF.');
  if(final && l.needs_review)throw new Error('Check the imported or generated wording and mark it reviewed before creating a signed final.');
  if(final) {
    showModal('Approve the signed letter',`<p>Create a signed PDF of <strong>${esc(l.title)}</strong> for <strong>${esc(studentName(l.student_id))}</strong>?</p><p class="muted">The current wording, recipient, date, and your signature will be saved as a new version. Previously saved versions remain available.</p><label class="check-label"><input type="checkbox" id="final-approved"><span>I have reviewed the letter’s content, recipient, and strength of endorsement, and approve adding my signature.</span></label><p id="modal-error" class="error-text"></p>`,`${button('Cancel','close-modal')}${button('Create signed PDF','confirm-final','primary')}`);
  } else await performBuild(false);
}
async function performBuild(final) {
  if(final && !$('#final-approved').checked)throw new Error('Please confirm that you have reviewed and approved the letter.');
  const id=state.letter,version=letterDraft(id)._version;
  const result=await api(`/api/letters/${encodeURIComponent(id)}/build`,{final,approved:final});
  if(final && $('#final-approved') && state.letter===id)closeModal();
  const l=await api(`/api/letters/${encodeURIComponent(id)}`),draft=letterDraft(id);if(draft?._version===version)state.letterDrafts.set(l.id,l);else if(draft)draft.revisions=l.revisions;cacheSavedLetter(l);if(state.view==='letters'&&state.letter===id){renderLetter();if(result.pdf_url)$('#build-result').innerHTML=`<div class="notice"><a href="${esc(result.pdf_url)}" target="_blank" rel="noopener">Open ${final?'signed final':'preview'} PDF ↗</a></div>`;}status();
  toast(final?'Signed final saved as a new version.':'Preview PDF is ready.');
}

